const initial = $('Webhook: Order Checkout Initiated').first().json.body || {};
const routerRes = $input.first().json.selectedVpa || {};

const orderId = initial.orderId || ('Order_' + Math.random().toString(36).substring(2, 10).toUpperCase());
const amount = parseFloat(initial.amount || 100).toFixed(2);
const payeeVpa = routerRes.vpaAddress || 'disha82@okaxis';
const payeeName = routerRes.holderName || 'DISHA Merchant Store';
const txnRef = 'TXN_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8).toUpperCase();

// NPCI UPI Specification v3.2 formatting
const params = new URLSearchParams({
  pa: payeeVpa,
  pn: payeeName,
  am: amount,
  tn: orderId,
  tr: txnRef,
  cu: 'INR'
});

const upiIntentUri = 'upi://pay?' + params.toString();

return [{
  json: {
    success: true,
    orderId,
    amount: parseFloat(amount),
    vpa: payeeVpa,
    bank: routerRes.bankName,
    healthScore: routerRes.healthScore,
    cooldownMinutes: routerRes.cooldownMinutes,
    upiIntentUri,
    qrData: upiIntentUri,
    expiresInSeconds: 180
  }
}];
